Column Type Notes id UUID PK, default gen_random_uuid() user_email VARCHAR(255) NOT NULL, indexed project_name VARCHAR(255) NOT NULL, indexed entries JSONB NOT NULL, dynamic field values due_date TIMESTAMPTZ nullable, indexed priority priority_level (ENUM) nullable archived BOOLEAN default false started_at TIMESTAMPTZ nullable, set when user starts a work session ended_at TIMESTAMPTZ nullable, set when user stops the session duration INTERVAL generated, <code>ended_at - started_at</code> deleted BOOLEAN default false — soft-delete flag created_at TIMESTAMPTZ default CURRENT_TIMESTAMP <pre><code>ALTER TABLE entries
ADD COLUMN due_date TIMESTAMP WITH TIME ZONE;

CREATE INDEX idx_entries_due_date ON entries(due_date);

CREATE TYPE priority_level AS ENUM (
  'Urgent and important',
  'Urgent but not important',
  'Not urgent, not important'
);

ALTER TABLE entries
ADD COLUMN priority priority_level;

ALTER TABLE projects
ADD COLUMN archived BOOLEAN DEFAULT false;

ALTER TABLE entries
ADD COLUMN archived BOOLEAN DEFAULT false;

CREATE INDEX idx_projects_archived ON projects(archived);
CREATE INDEX idx_entries_archived ON entries(archived);

ALTER TABLE entries
ADD COLUMN started_at TIMESTAMPTZ,
ADD COLUMN ended_at TIMESTAMPTZ,
ADD COLUMN duration INTERVAL GENERATED ALWAYS AS (ended_at - started_at) STORED;
</code></pre>
